function ensureFullWorkspaceContainer() {
  document.body.classList.add('full-width');
  if (!document.getElementById('hvs-fullwidth-override')) {
    const st = document.createElement('style');
    st.id = 'hvs-fullwidth-override';
    st.innerHTML = `
      body .layout-main,
      [data-page-route="Workspaces"] .layout-main,
      .page-container, .page-body, .container,
      .layout-main-section-wrapper, .layout-main-section,
      .codex-editor, .codex-editor__redactor, .ce-block, .ce-block__content,
      .custom-block-widget-box {
        max-width: 100% !important;
        width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
      }
      body .body-sidebar-container,
      body .dock,
      [data-page-route="Workspaces"] .layout-side-section,
      [data-page-route="Workspaces"] .page-head,
      .workspace-footer {
        display: none !important;
      }
      [data-page-route="Workspaces"] .layout-main {
        height: calc(100vh - var(--navbar-height, 48px)) !important;
      }
    `;
    document.head.appendChild(st);
  }
}
ensureFullWorkspaceContainer();
setTimeout(ensureFullWorkspaceContainer, 200);
setTimeout(ensureFullWorkspaceContainer, 800);

(function initWindowStyleBorderResize() {
  const board = root_element.getElementById('hvs-main-board');
  if (!board) return;
  let leftInset = 0, rightInset = 0;
  function applyBoxGeometry() {
    board.style.marginLeft = leftInset + 'px';
    board.style.marginRight = rightInset + 'px';
    board.style.width = `calc(100% - ${leftInset + rightInset}px)`;
  }
  function resetFullWidth() {
    leftInset = 0; rightInset = 0; board.style.minHeight = '';
    applyBoxGeometry();
    frappe.show_alert({ message: '↔️ 창 크기가 화면 전체 폭에 맞게 정렬되었습니다.', indicator: 'blue' });
  }
  function attachDrag(el, mode) {
    if (!el) return;
    el.ondblclick = resetFullWidth;
    el.onmousedown = (e) => {
      e.preventDefault(); e.stopPropagation();
      const startX = e.clientX, startY = e.clientY;
      const startLeft = leftInset, startRight = rightInset, startH = board.offsetHeight;
      const parentW = (board.parentElement ? board.parentElement.clientWidth : window.innerWidth) || window.innerWidth;
      const minW = 760;
      board.style.borderColor = '#2563eb';
      const onMove = (ev) => {
        const dx = ev.clientX - startX, dy = ev.clientY - startY;
        if (mode.includes('L')) leftInset = Math.max(0, Math.min(Math.max(0, parentW - rightInset - minW), startLeft + dx));
        if (mode.includes('R')) rightInset = Math.max(0, Math.min(Math.max(0, parentW - leftInset - minW), startRight - dx));
        if (mode.includes('B')) board.style.minHeight = Math.max(400, startH + dy) + 'px';
        applyBoxGeometry();
      };
      const onUp = () => {
        board.style.borderColor = '#cbd5e1';
        window.removeEventListener('mousemove', onMove);
        window.removeEventListener('mouseup', onUp);
      };
      window.addEventListener('mousemove', onMove);
      window.addEventListener('mouseup', onUp);
    };
  }
  attachDrag(root_element.getElementById('edge-left'), 'L');
  attachDrag(root_element.getElementById('edge-right'), 'R');
  attachDrag(root_element.getElementById('edge-bottom'), 'B');
  attachDrag(root_element.getElementById('corner-bl'), 'LB');
  attachDrag(root_element.getElementById('corner-br'), 'RB');
})();

