const STORAGE_KEY = 'hvs_simple_erp_v4';
let appState = {
  sidebarOpen: true,
  activeDept: 'dept_eq',       // 제일 왼쪽에서 선택된 부서(파트) ID (기본: 설비 파트)
  activeMenu: 'm_eq',          // 오른쪽 화면에서 현재 표시 중인 세부 창 (오직 1개만 단독 표시!)
  selectedAssetId: null,       // 장비 목록에서 특정 장비를 눌렀을 때 열리는 해당 장비 ID
  eqDetailTab: 'all',          // 장비 상세창 내부 서브탭 (all / gantt / sp / repair / pm)
  menus: JSON.parse(JSON.stringify(DEFAULT_MENUS)),
  formSchemas: JSON.parse(JSON.stringify(DEFAULT_FORM_SCHEMAS))
};

let cachedData = { pos: [], assets: [], spRows: [], repairs: [], pmLogs: [] };

async function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const p = JSON.parse(raw);
      if (p && p.menus && p.formSchemas) appState = { ...appState, ...p };
    }
    const dbRes = await frappe.db.get_value('HVS UI Config', 'simple_workspace_v4', 'config_json');
    if (dbRes && dbRes.message && dbRes.message.config_json) {
      const dbP = JSON.parse(dbRes.message.config_json);
      if (dbP && dbP.menus && dbP.formSchemas) {
        appState = { ...appState, ...dbP };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
      }
    }
  } catch(e) {}
}

async function saveState() {
  try {
    const str = JSON.stringify({
      sidebarOpen: appState.sidebarOpen,
      activeDept: appState.activeDept,
      activeMenu: appState.activeMenu,
      menus: appState.menus,
      formSchemas: appState.formSchemas
    });
    localStorage.setItem(STORAGE_KEY, str);
    const ex = await frappe.db.get_value('HVS UI Config', 'simple_workspace_v4', 'name');
    if (ex && ex.message && ex.message.name) {
      await frappe.db.set_value('HVS UI Config', 'simple_workspace_v4', 'config_json', str);
    } else {
      await frappe.db.insert({ doctype: 'HVS UI Config', config_key: 'simple_workspace_v4', config_json: str });
    }
  } catch(e) {}
}

