// 2. 제일 왼쪽 사이드바: 단순하게 부서(파트) 이름만 표시! (클릭 시 오른쪽에 세부 내용 표시)
// =========================================================================
function getDeptBadge(deptId) {
  if (deptId === 'dept_eq') return cachedData.assets.length + '대';
  if (deptId === 'dept_po') return cachedData.pos.length + '건';
  if (deptId === 'dept_maint') return (cachedData.repairs.length + cachedData.pmLogs.length) + '건';
  if (deptId === 'dept_acc') return cachedData.pos.length + '건';
  return '';
}

function renderSidebar() {
  const sb = root_element.getElementById('hvs-left-sidebar');
  const expBtn = root_element.getElementById('btn-expand-sb');
  if (!sb) return;
  sb.classList.toggle('collapsed', !appState.sidebarOpen);
  if (expBtn) expBtn.style.display = appState.sidebarOpen ? 'none' : 'inline-block';

  const nav = root_element.getElementById('sb-menu-list');
  let html = '';

  appState.menus.filter(d => d.enabled).forEach(dept => {
    const isActive = appState.activeDept === dept.id;
    const cnt = getDeptBadge(dept.id);
    html += `
      <div class="sb-menu-item ${isActive ? 'active' : ''}" data-dept-id="${dept.id}" style="padding:12px 14px; font-size:14.5px;">
        <span>${dept.label}</span>
        ${cnt ? `<span class="sb-cnt">${cnt}</span>` : ''}
      </div>
    `;
  });
  nav.innerHTML = html;

  nav.querySelectorAll('[data-dept-id]').forEach(el => {
    el.onclick = () => {
      const dId = el.getAttribute('data-dept-id');
      appState.activeDept = dId;
      appState.selectedAssetId = null;
      const deptObj = appState.menus.find(d => d.id === dId);
      if (deptObj && deptObj.subTabs && deptObj.subTabs.length) {
        appState.activeMenu = deptObj.subTabs[0].id;
      }
      saveState();
      renderSidebar();
      renderSingleStage();
    };
  });
}

// 좌측 부서(파트) 켜기/끄기 및 이름 편집 모달
window.openMenuCustomizerModal = function() {
  const d = new frappe.ui.Dialog({
    title: '⚙️ 왼쪽 부서(파트) 켜기/끄기 및 이름 편집',
    fields: [{ fieldname: 'menu_html', fieldtype: 'HTML' }],
    primary_action_label: '💾 부서 설정 저장',
    primary_action: async () => {
      const wrap = d.fields_dict.menu_html.$wrapper[0];
      wrap.querySelectorAll('.menu-edit-row').forEach((tr, idx) => {
        appState.menus[idx].label = tr.querySelector('.m-lbl').value;
        appState.menus[idx].enabled = tr.querySelector('.m-en').checked;
      });
      if (!appState.menus.some(m => m.enabled)) {
        appState.menus[0].enabled = true;
      }
      const curDept = appState.menus.find(m => m.id === appState.activeDept && m.enabled) || appState.menus.find(m => m.enabled);
      if (curDept) {
        appState.activeDept = curDept.id;
        if (!curDept.subTabs.some(st => st.id === appState.activeMenu)) {
          appState.activeMenu = curDept.subTabs[0].id;
        }
      }
      await saveState();
      renderSidebar();
      renderSingleStage();
      d.hide();
      frappe.show_alert({ message: '왼쪽 부서(파트) 표시 설정이 저장되었습니다!', indicator: 'green' });
    }
  });
  const wrap = d.fields_dict.menu_html.$wrapper[0];
  wrap.innerHTML = `
    <div style="font-size:12.5px; color:#475569; margin-bottom:10px;">
      왼쪽 창에 표시할 부서(파트)를 켜거나(✔) 끌 수 있습니다. (예: <b>🏭 설비 파트</b>만 체크해 두면 왼쪽에 설비 파트만 심플하게 표시됩니다.)
    </div>
    <table class="hvs-table">
      <thead>
        <tr>
          <th class="center" style="width:18%;">왼쪽 표시(ON/OFF)</th>
          <th style="width:42%;">부서(파트) 이름 (수정 가능)</th>
          <th style="width:40%;">오른쪽에 표시되는 세부 내용</th>
        </tr>
      </thead>
      <tbody>
        ${appState.menus.map((m) => `
          <tr class="menu-edit-row">
            <td class="center"><input type="checkbox" class="m-en" ${m.enabled ? 'checked' : ''} style="width:16px; height:16px;"></td>
            <td><input type="text" class="form-control input-sm m-lbl" value="${m.label}" style="font-weight:700;"></td>
            <td><small style="color:#475569;">${(m.subTabs || []).map(s => s.label).join(' · ')}</small></td>
          </tr>
        `).join('')}
      </tbody>
    </table>
  `;
  d.show();
};

// =========================================================================
// 3. 오른쪽 메인 화면: 선택한 부서(파트)의 세부 내용 중 1개의 창만 심플하게 렌더링!
// =========================================================================
window.switchRightSubTab = function(menuId) {
  appState.activeMenu = menuId;
  appState.selectedAssetId = null;
  saveState();
  renderSingleStage();
};

window.openEquipmentDetail = function(assetId, tab = 'all') {
  appState.selectedAssetId = assetId;
  appState.eqDetailTab = tab;
  renderSingleStage();
};

window.closeEquipmentDetail = function() {
  appState.selectedAssetId = null;
  renderSingleStage();
};

function buildDeptSubTabBarHtml() {
  const deptObj = appState.menus.find(d => d.id === appState.activeDept) || appState.menus[0];
  if (!deptObj || !deptObj.subTabs) return '';
  const buttons = deptObj.subTabs.map(st => {
    const isAct = (!appState.selectedAssetId && appState.activeMenu === st.id);
    return `<button class="eq-d-tab ${isAct ? 'active' : ''}" onclick="window.switchRightSubTab('${st.id}')">${st.label}</button>`;
  }).join('');
  return `
    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; border-bottom:2px solid #cbd5e1; padding-bottom:10px; margin-bottom:16px;">
      <div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center;">
        <span style="font-size:13.5px; font-weight:800; color:#0f172a; background:#e2e8f0; padding:6px 12px; border-radius:6px; margin-right:4px;">
          ${deptObj.label}
        </span>
        ${buttons}
      </div>
    </div>
  `;
}

function renderSingleStage() {
  const stage = root_element.getElementById('hvs-single-stage');
  if (!stage) return;

  const topSubBar = buildDeptSubTabBarHtml();

  // ★ 만약 [1. 장비 운용현황 · 목록]에서 특정 장비를 클릭한 상태라면 -> 그 장비의 전용 통합 상세창을 단독 표시!
  if (appState.selectedAssetId) {
    const eq = cachedData.assets.find(a => a.name === appState.selectedAssetId);
    if (eq) {
      stage.innerHTML = topSubBar + buildSingleEquipmentDetailView(eq);
      return;
    } else {
      appState.selectedAssetId = null;
    }
  }

  const mId = appState.activeMenu;

  // 1) 📊 장비 운용현황 · 보유장비 목록 (설비 파트 기본 첫 화면)
  if (mId === 'm_eq') {
    const totalEq = cachedData.assets.length;
    const opEq = cachedData.assets.filter(a => (a.custom_installation_status || '').includes('양산')).length;
    const satEq = totalEq - opEq;
    const pendingPo = cachedData.pos.filter(p => !((p.per_received || 0) >= 100 || (p.custom_delivery_stage || '').includes('5.'))).length;
    const overduePm = cachedData.pmLogs.filter(l => l.maintenance_status === 'Overdue').length;

    const eqRows = cachedData.assets.map(a => {
      const isOp = (a.custom_installation_status || '').includes('양산');
      const spCnt = cachedData.spRows.filter(s => s.asset_id === a.name).length;
      const repCnt = cachedData.repairs.filter(r => r.asset === a.name).length;
      const pmCnt = cachedData.pmLogs.filter(l => l.asset_name === a.name).length;
      return `
        <tr>
          <td>
            <span class="vendor-link" style="font-size:14px;" onclick="window.openEquipmentDetail('${a.name}')">
              🔍 ${a.custom_machine_no || a.name}
            </span>
          </td>
          <td><b>${a.custom_line_name || '-'}</b></td>
          <td>
            <span class="vendor-link" onclick="window.openEquipmentDetail('${a.name}')">${a.asset_name}</span>
            <br><small style="color:#64748b;">모델: ${a.custom_model_no || '-'} | NC: ${a.custom_controller_spec || '-'} | 제조사: ${a.custom_maker || '-'}</small>
            ${renderCustomExtraBadges('eq', a)}
          </td>
          <td class="right"><b>${fmtKRW(a.net_purchase_amount)}</b></td>
          <td class="center"><span class="tag ${isOp ? 'green' : 'amber'}">${a.custom_installation_status || '-'}</span></td>
          <td class="center">
            <span class="tag blue">부품 ${spCnt}종</span>
            <span class="tag red">수리 ${repCnt}건</span>
            <span class="tag purple">PM ${pmCnt}건</span>
          </td>
          <td class="center"><b>${a.custom_next_pm_date || '-'}</b></td>
          <td class="center" style="white-space:nowrap;">
            <button class="hvs-btn primary sm" onclick="window.openEquipmentDetail('${a.name}')">📂 이 장비 상세열기</button>
            <button class="hvs-btn outline sm" onclick="window.openQuickEqModal('${a.name}')">✏️ 수정</button>
            <button class="hvs-btn danger-outline sm" onclick="window.deleteRecord('Asset','${a.name}','${a.asset_name}')">🗑️ 삭제</button>
          </td>
        </tr>
      `;
    }).join('');

    stage.innerHTML = topSubBar + `
      <div class="stage-hdr">
        <div>
          <div class="stage-title">📊 전체 장비 운용 현황 및 보유 장비 목록</div>
          <div class="stage-sub">장비명을 클릭하면 해당 장비의 [일정 · 수리 기술문서 · 부품 단가표 · PM 주기] 전용 창이 한눈에 열립니다.</div>
        </div>
        <div class="stage-actions">
          <button class="hvs-btn outline" onclick="window.openFormSchemaEditor('eq')">✏️ 장비 등록양식 편집</button>
