        </div>
      </div>

      <div class="simple-kpi-row">
        <div class="simple-kpi green">
          <div class="k-lbl">전체 보유 장비 (양산가동 / 시운전)</div>
          <div class="k-val">총 ${totalEq}대 (가동 ${opEq} / 시운전 ${satEq})</div>
        </div>
        <div class="simple-kpi amber">
          <div class="k-lbl">발주 · 입고 진행중 장비/부품</div>
          <div class="k-val">${pendingPo}건 진행중</div>
        </div>
        <div class="simple-kpi">
          <div class="k-lbl">등록된 장비별 부품 단가</div>
          <div class="k-val">총 ${cachedData.spRows.length}종</div>
        </div>
        <div class="simple-kpi red">
          <div class="k-lbl">수리 기술문서 / 기한경과 PM</div>
          <div class="k-val">문서 ${cachedData.repairs.length}건 / PM경과 ${overduePm}건</div>
        </div>
      </div>

      <div class="hvs-table-wrap">
        <table class="hvs-table">
          <thead>
            <tr>
              <th>호기 번호 (클릭시 상세)</th>
              <th>설치 라인·공정</th>
              <th>장비명 / 모델 / 컨트롤러 / 제조사</th>
              <th class="right">도입 단가</th>
              <th class="center">현재 운용상태</th>
              <th class="center">보유 부품·수리·PM 현황</th>
              <th class="center">차기 PM 예정일</th>
              <th class="center">장비 상세열기 / 수정 / 삭제</th>
            </tr>
          </thead>
          <tbody>${eqRows || '<tr><td colspan="8" class="center" style="padding:30px;">등록된 장비가 없습니다. 우측 상단 [+ 신규 장비 등록]을 눌러 장비를 등록하세요.</td></tr>'}</tbody>
        </table>
      </div>
    `;
    return;
  }

  // 2) 📅 발주 · 입고 간트차트 (단독 화면)
  if (mId === 'm_gantt') {
    stage.innerHTML = topSubBar + `
      <div class="stage-hdr">
        <div>
          <div class="stage-title">📅 장비·부품 발주 및 입고(납기) 간트차트</div>
          <div class="stage-sub">발주일~입고일을 달력으로 바로 수정할 수 있으며, 공급업체나 막대를 클릭하면 [일자별 세부 공정 간트차트]가 열립니다.</div>
        </div>
        <div class="stage-actions">
          <button class="hvs-btn outline" onclick="window.openFormSchemaEditor('po')">✏️ 발주 양식 편집</button>
          <button class="hvs-btn primary" onclick="window.openQuickPOModal()">➕ 신규 발주·일정 등록</button>
