  }

  // 3) 🔩 장비별 부품 · 단가표 (단독 화면)
  if (mId === 'm_sp') {
    stage.innerHTML = topSubBar + `
      <div class="stage-hdr">
        <div>
          <div class="stage-title">🔩 장비(호기)별 유지보수 부품(Spare Parts) 및 단가표</div>
          <div class="stage-sub">각 장비에 장착되는 소모품·예비부품의 규격, 단가, 대당 소요량, 교체주기를 관리합니다.</div>
        </div>
        <div class="stage-actions">
          <button class="hvs-btn outline" onclick="window.openFormSchemaEditor('sp')">✏️ 부품 양식 편집</button>
          <button class="hvs-btn teal" onclick="window.openQuickSpareModal(null, null)">➕ 장비 부품·단가 추가</button>
        </div>
      </div>
      ${buildSparePartsTableHtml(cachedData.spRows)}
    `;
    return;
  }

  // 4) 📄 고장 · 수리 기술문서 (단독 화면)
  if (mId === 'm_repair') {
    stage.innerHTML = topSubBar + `
      <div class="stage-hdr">
        <div>
          <div class="stage-title">📄 설비 고장 · 수리 기술문서 및 보고서 (Technical Report)</div>
          <div class="stage-sub">장비 고장 알람코드, 근본 원인, 수리 기술조치 내역, 파라미터 측정치 및 재발방지 대책을 기록·인쇄합니다.</div>
