  // 7) 🛒 발주 · 대금결제 내역 (단독 화면)
  if (mId === 'm_po') {
    stage.innerHTML = topSubBar + `
      <div class="stage-hdr">
        <div>
          <div class="stage-title">🛒 장비·부품 발주 내역 및 대금 결제조건(계약/중도/잔금)</div>
          <div class="stage-sub">공급업체별 발주 금액, 진행단계, 계약금/중도금/잔금 조건을 관리합니다.</div>
        </div>
        <div class="stage-actions">
          <button class="hvs-btn outline" onclick="window.openFormSchemaEditor('po')">✏️ 발주 양식 편집</button>
          <button class="hvs-btn primary" onclick="window.openQuickPOModal()">➕ 신규 발주 등록</button>
        </div>
      </div>
      ${buildPoTableHtml(cachedData.pos)}
    `;
    return;
  }

  // 8) 💰 회계 파트 전용: 설비 투자비(CAPEX) · 대금결제 · 수리비 정산 (단독 화면)
  if (mId === 'm_acc') {
    const totalAssetVal = cachedData.assets.reduce((s, a) => s + Number(a.net_purchase_amount || 0), 0);
    const totalPoNet = cachedData.pos.reduce((s, p) => s + Number(p.net_total || 0), 0);
    const totalPoGrand = cachedData.pos.reduce((s, p) => s + Number(p.grand_total || 0), 0);
    const totalRepCost = cachedData.repairs.reduce((s, r) => s + Number(r.total_repair_cost || r.repair_cost || 0), 0);
    stage.innerHTML = topSubBar + `
      <div class="stage-hdr">
        <div>
          <div class="stage-title">💰 설비 투자비(CAPEX) · 발주 대금결제 · 수리비 정산 현황</div>
          <div class="stage-sub">신공장 장비 취득원가, 발주 공급가액/부가세 합계, 유지보수 수리 비용을 한눈에 정산합니다.</div>
        </div>
      </div>
      <div class="simple-kpi-row">
        <div class="simple-kpi green">
          <div class="k-lbl">보유 설비 취득원가 합계 (${cachedData.assets.length}대)</div>
          <div class="k-val">${fmtKRW(totalAssetVal)}</div>
        </div>
        <div class="simple-kpi">
          <div class="k-lbl">발주 공급가액 합계 (VAT 별도)</div>
          <div class="k-val">${fmtKRW(totalPoNet)}</div>
        </div>
        <div class="simple-kpi amber">
          <div class="k-lbl">발주 총 결제금액 (VAT 포함)</div>
          <div class="k-val">${fmtKRW(totalPoGrand)}</div>
        </div>
        <div class="simple-kpi red">
          <div class="k-lbl">누적 외주·부품 수리비용 (${cachedData.repairs.length}건)</div>
          <div class="k-val">${fmtKRW(totalRepCost)}</div>
        </div>
      </div>
      ${buildPoTableHtml(cachedData.pos)}
    `;
    return;
  }
}

