function buildSingleEquipmentDetailView(eq) {
  const mySp = cachedData.spRows.filter(s => s.asset_id === eq.name);
  const myRep = cachedData.repairs.filter(r => r.asset === eq.name || r.asset_name === eq.asset_name);
  const myPm = cachedData.pmLogs.filter(l => l.asset_name === eq.name || l.asset_name === eq.asset_name);
  const mNo = (eq.custom_machine_no || '').split(' ')[0].toLowerCase();
  const mod = (eq.custom_model_no || '').toLowerCase();
  const myPos = cachedData.pos.filter(p => {
    const m = (p.custom_target_machine || '').toLowerCase();
    return (mNo && m.includes(mNo)) || (mod && m.includes(mod));
  });

  const tab = appState.eqDetailTab || 'all';
  const chkCnt = [eq.custom_chk_utility, eq.custom_chk_leveling, eq.custom_chk_test_cut, eq.custom_chk_training].filter(Boolean).length;

  let subContent = '';
  if (tab === 'all') {
    subContent = `
      <div style="display:flex; flex-direction:column; gap:20px;">
        <div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:15px; font-weight:800;">📅 1. 이 장비의 발주 · 입고 · 설치 일정 간트차트 (${myPos.length}건)</span>
            <button class="hvs-btn primary sm" onclick="window.openQuickPOModal('${eq.name}', true)">➕ 이 장비 관련 발주/일정 추가</button>
          </div>
          ${buildGanttTableHtml(myPos)}
        </div>
        <div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:15px; font-weight:800;">🔩 2. 이 장비의 유지보수 부품(Spare Parts) 및 단가표 (${mySp.length}종)</span>
            <button class="hvs-btn teal sm" onclick="window.openQuickSpareModal('${eq.name}', null)">➕ 이 장비 부품·단가 추가</button>
          </div>
          ${buildSparePartsTableHtml(mySp)}
        </div>
        <div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:15px; font-weight:800;">📄 3. 이 장비의 고장 · 수리 기술문서 및 보고서 (${myRep.length}건)</span>
            <button class="hvs-btn red sm" onclick="window.openQuickRepairModal(null, '${eq.name}')">➕ 이 장비 수리 기술보고서 작성</button>
          </div>
          ${buildRepairTableHtml(myRep)}
        </div>
        <div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:15px; font-weight:800;">🗓️ 4. 이 장비의 정기 예방정비(PM) 스케줄 (${myPm.length}건)</span>
            <button class="hvs-btn purple sm" onclick="window.openQuickPMModal(null, '${eq.name}')">➕ 이 장비 PM 점검일정 추가</button>
          </div>
          ${buildPmTableHtml(myPm)}
        </div>
      </div>
    `;
  } else if (tab === 'gantt') {
    subContent = buildGanttTableHtml(myPos);
  } else if (tab === 'sp') {
    subContent = buildSparePartsTableHtml(mySp);
  } else if (tab === 'repair') {
    subContent = buildRepairTableHtml(myRep);
  } else if (tab === 'pm') {
    subContent = buildPmTableHtml(myPm);
  }

  return `
    <div class="stage-hdr">
      <div style="display:flex; align-items:center; gap:12px;">
        <button class="hvs-btn outline" onclick="window.closeEquipmentDetail()" style="font-weight:800;">← 전체 장비 목록으로 돌아가기</button>
        <div>
          <div class="stage-title">🎯 [${eq.custom_machine_no || eq.name}] ${eq.asset_name} — 장비 통합 관리창</div>
          <div class="stage-sub">
            라인: <b>${eq.custom_line_name || '-'}</b> | 제조사: <b>${eq.custom_maker || '-'}</b> | 모델: <b>${eq.custom_model_no || '-'}</b> | 컨트롤러: <b>${eq.custom_controller_spec || '-'}</b> | 취득단가: <b>${fmtKRW(eq.net_purchase_amount)}</b> | 시운전검수: <b>${chkCnt}/4 완료</b>
          </div>
        </div>
      </div>
      <div class="stage-actions">
        <button class="hvs-btn outline" onclick="window.openQuickEqModal('${eq.name}')">✏️ 장비 제원·시운전 수정</button>
        <button class="hvs-btn outline" onclick="frappe.set_route('print','Asset','${eq.name}')">🖨️ 장비 명세서 인쇄</button>
      </div>
    </div>

    <!-- 장비 상세 서브탭 -->
    <div class="eq-detail-tabs">
      <button class="eq-d-tab ${tab==='all'?'active':''}" onclick="window.openEquipmentDetail('${eq.name}','all')">📋 이 장비 전체 한눈에 보기</button>
      <button class="eq-d-tab ${tab==='gantt'?'active':''}" onclick="window.openEquipmentDetail('${eq.name}','gantt')">📅 일정·발주 간트 (${myPos.length})</button>
      <button class="eq-d-tab ${tab==='sp'?'active':''}" onclick="window.openEquipmentDetail('${eq.name}','sp')">🔩 부품·단가표 (${mySp.length})</button>
      <button class="eq-d-tab ${tab==='repair'?'active':''}" onclick="window.openEquipmentDetail('${eq.name}','repair')">📄 수리 기술문서 (${myRep.length})</button>
      <button class="eq-d-tab ${tab==='pm'?'active':''}" onclick="window.openEquipmentDetail('${eq.name}','pm')">🗓️ 정기 PM 점검 (${myPm.length})</button>
    </div>

    ${subContent}
  `;
}

