// 5. 각 파트별 깔끔한 표 생성 함수들
// =========================================================================
function buildGanttTableHtml(posList) {
  const todayStr = frappe.datetime.get_today();
  const minDate = frappe.datetime.add_days(todayStr, -35);
  const totalSpanDays = 70;
  const dateToPct = (dStr) => {
    if (!dStr) return 50;
    return Math.max(2, Math.min(96, Math.round((frappe.datetime.get_diff(dStr, minDate) / totalSpanDays) * 100)));
  };
  const todayPct = dateToPct(todayStr);
  let headerTicks = '';
  for (let i = 0; i <= 7; i++) headerTicks += `<span>${frappe.datetime.add_days(minDate, i * 10).substring(5)}</span>`;

  const rows = posList.map(po => {
    const sPct = dateToPct(po.transaction_date);
    const ePct = Math.max(sPct + 8, dateToPct(po.schedule_date));
    const width = Math.min(98 - sPct, ePct - sPct);
    const isDone = (po.per_received || 0) >= 100 || (po.custom_delivery_stage || '').includes('5.');
    const titleLabel = `${po.supplier_name} (${po.custom_target_machine || po.name})`;
    return `
      <tr>
        <td>
          <span class="vendor-link" onclick="window.openVendorDetailGanttModal('${po.name}')">🔍 ${po.supplier_name}</span>
          <br><small style="color:#475569; font-weight:700;">${po.custom_target_machine || po.name}</small>
        </td>
        <td><b>${po.custom_target_line || '-'}</b></td>
        <td class="center" style="white-space:nowrap;">
          <input type="date" class="inline-date-inp" value="${po.transaction_date || ''}" onchange="window.updatePoDatesInline('${po.name}', this.value, '${po.schedule_date || po.transaction_date}')">
          ~
          <input type="date" class="inline-date-inp" value="${po.schedule_date || ''}" onchange="window.updatePoDatesInline('${po.name}', '${po.transaction_date}', this.value)" style="color:#dc2626;">
        </td>
        <td class="center"><span class="tag ${isDone ? 'green' : 'blue'}">${po.custom_delivery_stage || '진행중'}</span></td>
        <td class="gantt-timeline-cell" onclick="window.openVendorDetailGanttModal('${po.name}')" title="클릭하면 일자별 세부 공정 간트차트가 열립니다">
          <div class="gantt-today-line" style="left:${todayPct}%;"></div>
          <div class="gantt-bar ${isDone ? 'green' : 'blue'}" style="left:${sPct}%; width:${width}%;">
            ${po.supplier_name} · ${po.custom_target_machine || ''} (${(po.transaction_date||'').substring(5)}~${(po.schedule_date||'').substring(5)})
          </div>
        </td>
        <td class="center" style="white-space:nowrap;">
          <button class="hvs-btn primary sm" onclick="window.openVendorDetailGanttModal('${po.name}')">📅 상세간트</button>
          ${!isDone ? `<button class="hvs-btn green sm" onclick="window.completeRecord('Purchase Order','${po.name}','${titleLabel}')">✔ 완료</button>` : ''}
          <button class="hvs-btn danger-outline sm" onclick="window.deleteRecord('Purchase Order','${po.name}','${titleLabel}')">🗑️ 삭제</button>
        </td>
      </tr>
    `;
  }).join('');

  return `
    <table class="gantt-table">
      <thead>
        <tr>
          <th style="width:18%;">발주 업체 · 설비명 (클릭시 상세)</th>
          <th style="width:13%;">투입 라인</th>
          <th style="width:20%;">발주일 ~ 입고일 (직접 클릭 수정)</th>
          <th style="width:11%;">현재 단계</th>
          <th style="width:28%; position:relative;">
            <div>발주 ~ 입고 타임라인 <span style="color:#dc2626;">▼ 오늘(${todayStr.substring(5)})</span></div>
            <div class="gantt-date-ticks">${headerTicks}</div>
          </th>
          <th style="width:10%;">상세 / 완료 / 삭제</th>
        </tr>
      </thead>
      <tbody>${rows || '<tr><td colspan="6" class="center" style="padding:20px;">발주 일정이 없습니다.</td></tr>'}</tbody>
    </table>
  `;
}

