function buildTreeHtml(assetsList) {
  const byLine = {};
  assetsList.forEach(a => {
    const ln = a.custom_line_name || '기타 라인';
    if (!byLine[ln]) byLine[ln] = [];
    byLine[ln].push(a);
  });
  return Object.keys(byLine).map(ln => {
    const eqCards = byLine[ln].map(a => {
      const mySp = cachedData.spRows.filter(s => s.asset_id === a.name);
      const myRep = cachedData.repairs.filter(r => r.asset === a.name);
      const myPm = cachedData.pmLogs.filter(l => l.asset_name === a.name);
      return `
        <div style="border:1px solid #cbd5e1; border-left:4px solid #2563eb; border-radius:8px; padding:12px; margin-bottom:10px; background:#fff;">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <div>
              <span class="vendor-link" style="font-size:14px;" onclick="window.openEquipmentDetail('${a.name}')">🏭 [${a.custom_machine_no || a.name}] ${a.asset_name}</span>
              <span style="color:#64748b; font-size:12px; margin-left:8px;">(${a.custom_maker || '-'} / ${a.custom_model_no || '-'} / ${fmtKRW(a.net_purchase_amount)})</span>
            </div>
            <button class="hvs-btn primary sm" onclick="window.openEquipmentDetail('${a.name}')">📂 이 장비 상세열기</button>
          </div>
          <div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; font-size:12px;">
            <div style="background:#f8fafc; padding:8px; border-radius:6px; border:1px solid #e2e8f0;">
              <b style="color:#0d9488;">🔩 부품·단가 (${mySp.length}종)</b>
              ${mySp.map(s => `<div style="margin-top:4px; display:flex; justify-content:space-between;"><span>• ${s.part_name}</span><b>${fmtKRW(s.unit_price)}</b></div>`).join('') || '<div style="color:#94a3b8; margin-top:4px;">없음</div>'}
            </div>
            <div style="background:#f8fafc; padding:8px; border-radius:6px; border:1px solid #e2e8f0;">
              <b style="color:#dc2626;">📄 수리 기술문서 (${myRep.length}건)</b>
              ${myRep.map(r => `<div style="margin-top:4px;">• [${r.custom_doc_no || r.name}] ${r.custom_failure_category || ''}</div>`).join('') || '<div style="color:#94a3b8; margin-top:4px;">없음</div>'}
            </div>
            <div style="background:#f8fafc; padding:8px; border-radius:6px; border:1px solid #e2e8f0;">
              <b style="color:#7c3aed;">🗓️ 정기 PM (${myPm.length}건)</b>
              ${myPm.map(l => `<div style="margin-top:4px; display:flex; justify-content:space-between;"><span>• ${l.task_name.substring(0, 18)}..</span><b>${l.due_date || '-'}</b></div>`).join('') || '<div style="color:#94a3b8; margin-top:4px;">없음</div>'}
            </div>
          </div>
        </div>
      `;
    }).join('');
    return `
      <div style="margin-bottom:16px; background:#f8fafc; border:1px solid #cbd5e1; border-radius:10px; padding:12px;">
        <div style="font-size:15px; font-weight:800; color:#0f172a; margin-bottom:10px;">📂 ${ln} (${byLine[ln].length}대)</div>
        ${eqCards}
      </div>
    `;
  }).join('');
}

