window.openFormSchemaEditor = function(initialFormKey = 'eq') {
  let currentKey = initialFormKey || 'eq';
  const d = new frappe.ui.Dialog({
    title: '🛠️ 입력 폼(양식) 항목 편집기 — 필요한 항목만 켜고 라벨·기본값을 수정하세요',
    size: 'extra-large',
    fields: [{ fieldname: 'studio_html', fieldtype: 'HTML' }],
    primary_action_label: '💾 양식 저장 및 즉시 적용',
    primary_action: async () => {
      saveCurrentTabEdits();
      await saveState();
      frappe.show_alert({ message: '✔ 양식이 저장되었습니다!', indicator: 'green' });
      d.hide();
      renderSingleStage();
    }
  });

  function saveCurrentTabEdits() {
    const wrap = d.fields_dict.studio_html.$wrapper[0];
    const rows = wrap.querySelectorAll('.schema-field-row');
    if (!rows.length) return;
    const updatedFields = [];
    rows.forEach(tr => {
      updatedFields.push({
        fieldname: tr.getAttribute('data-fname'),
        label: tr.querySelector('.sf-label').value,
        fieldtype: tr.querySelector('.sf-type').value,
        default: tr.querySelector('.sf-default').value,
        options: tr.querySelector('.sf-options').value.replace(/,\s*/g, '\n'),
        visible: tr.querySelector('.sf-vis').checked,
        isCustom: tr.getAttribute('data-custom') === '1'
      });
    });
    appState.formSchemas[currentKey].fields = updatedFields;
  }

  function renderStudio() {
    const wrap = d.fields_dict.studio_html.$wrapper[0];
    const schema = appState.formSchemas[currentKey];
    const formTabsHtml = Object.keys(appState.formSchemas).map(k => `
      <button class="hvs-btn ${k === currentKey ? 'primary' : 'outline'} sm" data-switch-fkey="${k}">
        ${appState.formSchemas[k].title}
      </button>
    `).join('');

    const rowsHtml = schema.fields.map((f, idx) => `
      <tr class="schema-field-row" data-fname="${f.fieldname}" data-custom="${f.isCustom ? '1' : '0'}">
        <td class="center"><b>${idx + 1}</b></td>
        <td class="center"><input type="checkbox" class="sf-vis" ${f.visible !== false ? 'checked' : ''} style="width:16px; height:16px;"></td>
        <td><input type="text" class="form-control input-sm sf-label" value="${f.label || ''}" style="font-weight:700;"></td>
        <td>
          <select class="form-control input-sm sf-type" ${f.isCustom ? '' : 'disabled'}>
            <option value="Data" ${f.fieldtype==='Data'?'selected':''}>일반 텍스트</option>
            <option value="Select" ${f.fieldtype==='Select'?'selected':''}>선택 목록</option>
            <option value="Currency" ${f.fieldtype==='Currency'?'selected':''}>금액/단가</option>
            <option value="Float" ${f.fieldtype==='Float'?'selected':''}>수량/숫자</option>
            <option value="Int" ${f.fieldtype==='Int'?'selected':''}>정수</option>
            <option value="Date" ${f.fieldtype==='Date'?'selected':''}>날짜</option>
            <option value="Datetime" ${f.fieldtype==='Datetime'?'selected':''}>일시</option>
            <option value="Check" ${f.fieldtype==='Check'?'selected':''}>체크박스</option>
            <option value="Small Text" ${f.fieldtype==='Small Text'?'selected':''}>장문 메모</option>
          </select>
        </td>
        <td><input type="text" class="form-control input-sm sf-default" value="${f.default || ''}"></td>
        <td><input type="text" class="form-control input-sm sf-options" value="${(f.options || '').replace(/\n/g, ', ')}"></td>
        <td class="center" style="white-space:nowrap;">
          <button class="btn btn-xs btn-default btn-sf-up" data-idx="${idx}">▲</button>
          <button class="btn btn-xs btn-default btn-sf-dn" data-idx="${idx}">▼</button>
          ${f.isCustom ? `<button class="btn btn-xs btn-danger btn-sf-del" data-idx="${idx}">🗑️</button>` : ''}
        </td>
      </tr>
    `).join('');

    wrap.innerHTML = `
      <div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:12px;">${formTabsHtml}</div>
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
        <b style="font-size:14px;">${schema.title}</b>
        <div style="display:flex; gap:6px;">
          <button class="btn btn-xs btn-primary" id="btn-add-custom-field">➕ 새 입력항목 추가</button>
          <button class="btn btn-xs btn-default" id="btn-reset-schema">🔄 기본값 복원</button>
        </div>
      </div>
      <table class="hvs-table">
        <thead>
          <tr>
            <th class="center" style="width:6%;">순서</th>
            <th class="center" style="width:7%;">표시</th>
            <th style="width:25%;">항목명 (라벨)</th>
            <th style="width:15%;">형태</th>
            <th style="width:18%;">기본값</th>
            <th style="width:19%;">선택지 (콤마 구분)</th>
            <th class="center" style="width:10%;">이동/삭제</th>
          </tr>
        </thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    `;

    wrap.querySelectorAll('[data-switch-fkey]').forEach(btn => {
      btn.onclick = () => { saveCurrentTabEdits(); currentKey = btn.getAttribute('data-switch-fkey'); renderStudio(); };
    });
    wrap.querySelector('#btn-add-custom-field').onclick = () => {
      saveCurrentTabEdits();
      appState.formSchemas[currentKey].fields.push({
        fieldname: 'extra_' + Math.floor(1000 + Math.random() * 9000),
        label: '추가 입력 항목', fieldtype: 'Data', default: '', options: '', visible: true, isCustom: true
      });
      renderStudio();
    };
    wrap.querySelector('#btn-reset-schema').onclick = () => {
      appState.formSchemas[currentKey] = JSON.parse(JSON.stringify(DEFAULT_FORM_SCHEMAS[currentKey]));
      renderStudio();
    };
    wrap.querySelectorAll('.btn-sf-up').forEach(btn => {
      btn.onclick = () => {
        saveCurrentTabEdits();
        const i = Number(btn.getAttribute('data-idx'));
        if (i > 0) { const a = appState.formSchemas[currentKey].fields; [a[i-1], a[i]] = [a[i], a[i-1]]; renderStudio(); }
      };
    });
    wrap.querySelectorAll('.btn-sf-dn').forEach(btn => {
      btn.onclick = () => {
        saveCurrentTabEdits();
        const i = Number(btn.getAttribute('data-idx'));
        const a = appState.formSchemas[currentKey].fields;
        if (i < a.length - 1) { [a[i+1], a[i]] = [a[i], a[i+1]]; renderStudio(); }
      };
    });
    wrap.querySelectorAll('.btn-sf-del').forEach(btn => {
      btn.onclick = () => {
        saveCurrentTabEdits();
        appState.formSchemas[currentKey].fields.splice(Number(btn.getAttribute('data-idx')), 1);
        renderStudio();
      };
    });
  }
  d.show();
  renderStudio();
};

function resolveDefaultVal(defStr) {
  if (!defStr) return '';
  if (defStr === 'TODAY') return frappe.datetime.get_today();
  if (defStr.startsWith('TODAY+')) return frappe.datetime.add_days(frappe.datetime.get_today(), Number(defStr.replace('TODAY+', '')) || 7);
  if (defStr === 'NOW') return frappe.datetime.now_datetime();
  if (defStr === 'AUTO_DOC_NO') return `TECH-REP-2026-00${Math.floor(Math.random() * 80 + 10)}`;
  return defStr;
}

function buildDialogFieldsFromSchema(formKey, existingDoc = null, assetOptions = [], extraOverrides = {}) {
  const schema = (appState.formSchemas && appState.formSchemas[formKey]) || DEFAULT_FORM_SCHEMAS[formKey];
  let extraValues = {};
  if (existingDoc && existingDoc.custom_extra_fields_json) {
    try { extraValues = JSON.parse(existingDoc.custom_extra_fields_json); } catch(e) {}
  }
  const visibleFields = schema.fields.filter(f => f.visible !== false);
  const out = [];
  const halfPoint = Math.ceil(visibleFields.length / 2);

  visibleFields.forEach((f, idx) => {
    if (idx === halfPoint && visibleFields.length >= 4) out.push({ fieldtype: 'Column Break' });
    let val = undefined;
    if (extraOverrides[f.fieldname] !== undefined) {
      val = extraOverrides[f.fieldname];
    } else if (existingDoc) {
      if (f.isCustom) val = extraValues[f.fieldname];
      else if (f.fieldname === 'supplier_text') val = existingDoc.supplier_name || existingDoc.supplier;
      else if (f.fieldname === 'item_text') val = (existingDoc.items && existingDoc.items[0]) ? existingDoc.items[0].item_name : '';
      else if (f.fieldname === 'qty') val = (existingDoc.items && existingDoc.items[0]) ? existingDoc.items[0].qty : 1;
      else if (f.fieldname === 'rate') val = (existingDoc.items && existingDoc.items[0]) ? existingDoc.items[0].rate : 0;
      else val = existingDoc[f.fieldname];
    }
    if (val === undefined || val === null || val === '') {
      if (f.options === 'ASSET_LIST') val = appState.selectedAssetId || (assetOptions[0] && assetOptions[0].value) || '';
      else val = resolveDefaultVal(f.default);
    }
    if (['Currency', 'Float', 'Int', 'Check'].includes(f.fieldtype)) val = Number(val || 0);
    const df = { fieldname: f.fieldname, label: f.label, fieldtype: f.fieldtype, default: val };
    if (f.fieldtype === 'Select') df.options = f.options === 'ASSET_LIST' ? assetOptions : f.options;
    out.push(df);
  });
  return out;
}

function extractExtraFieldsJson(formKey, vals, existingDoc = null) {
  const schema = (appState.formSchemas && appState.formSchemas[formKey]) || DEFAULT_FORM_SCHEMAS[formKey];
  let extra = {};
  if (existingDoc && existingDoc.custom_extra_fields_json) {
    try { extra = JSON.parse(existingDoc.custom_extra_fields_json); } catch(e) {}
  }
  schema.fields.forEach(f => {
    if (f.isCustom && vals[f.fieldname] !== undefined) extra[f.fieldname] = vals[f.fieldname];
  });
  return JSON.stringify(extra);
}

function renderCustomExtraBadges(formKey, docObj) {
  if (!docObj || !docObj.custom_extra_fields_json) return '';
  let extra = {};
  try { extra = JSON.parse(docObj.custom_extra_fields_json); } catch(e) { return ''; }
  const schema = (appState.formSchemas && appState.formSchemas[formKey]) || DEFAULT_FORM_SCHEMAS[formKey];
  const badges = [];
  schema.fields.forEach(f => {
    if (f.isCustom && extra[f.fieldname]) badges.push(`<span class="tag purple" style="margin-right:3px;">${f.label}: ${extra[f.fieldname]}</span>`);
  });
  return badges.length ? `<div style="margin-top:3px;">${badges.join('')}</div>` : '';
}

