async function ensureSupplier(supplierName) {
  const name = (supplierName || '기본 공급업체').trim();
  const r = await frappe.db.get_value('Supplier', name, 'name');
  if (r && r.message && r.message.name) return r.message.name;
  const doc = await frappe.db.insert({ doctype: 'Supplier', supplier_name: name, supplier_group: '설비·공작기계 제조사 (Equipment Maker)' });
  return doc.name;
}

async function ensureItem(itemNameOrCode, isAsset = true) {
  const txt = (itemNameOrCode || (isAsset ? '신규 도입장비' : '신규 예비부품')).trim();
  const byCode = await frappe.db.get_value('Item', txt, 'name');
  if (byCode && byCode.message && byCode.message.name) return byCode.message.name;
  const byName = await frappe.db.get_list('Item', { filters: { item_name: txt }, fields: ['name'], limit: 1 });
  if (byName && byName.length > 0) return byName[0].name;
  const newItem = await frappe.db.insert({
    doctype: 'Item', item_code: (isAsset ? 'EQ-' : 'SP-') + Math.floor(1000 + Math.random() * 9000), item_name: txt,
    item_group: isAsset ? 'CNC 선반·터닝센터 (CNC Lathe)' : '스핀들·베어링·구동부품 (Spindle/Bearing)',
    stock_uom: 'Nos', is_stock_item: isAsset ? 0 : 1, is_fixed_asset: isAsset ? 1 : 0,
    asset_category: isAsset ? 'CNC·MCT 핵심가공설비' : null, auto_create_assets: 0
  });
  return newItem.name;
}

