function buildDefaultSubTasks(startDate, endDate) {
  const s = startDate || frappe.datetime.get_today();
  const totalDays = Math.max(12, frappe.datetime.get_diff(endDate || frappe.datetime.add_days(s, 30), s));
  return [
    { step: '1. 발주 확정 · 계약금 지급', start: s, end: frappe.datetime.add_days(s, Math.round(totalDays*0.12)), status: '완료', note: '발주서 교부 및 선급금 집행' },
    { step: '2. 메이커 설비 본체 제작', start: frappe.datetime.add_days(s, Math.round(totalDays*0.12)), end: frappe.datetime.add_days(s, Math.round(totalDays*0.60)), status: '진행중', note: '주축·베드·컨트롤러 조립' },
    { step: '3. 출하 전 검사 (FAT)', start: frappe.datetime.add_days(s, Math.round(totalDays*0.60)), end: frappe.datetime.add_days(s, Math.round(totalDays*0.75)), status: '대기', note: '메이커 공장 입회 검사' },
    { step: '4. 신공장 입고 · 라인 안착', start: frappe.datetime.add_days(s, Math.round(totalDays*0.75)), end: frappe.datetime.add_days(s, Math.round(totalDays*0.88)), status: '대기', note: '반입 및 기초 레벨링' },
    { step: '5. 시운전(SAT) · 잔금정산', start: frappe.datetime.add_days(s, Math.round(totalDays*0.88)), end: frappe.datetime.add_days(s, totalDays), status: '대기', note: '샘플가공 합격 후 인수' }
  ];
}

window.openVendorDetailGanttModal = async function(poName) {
  const po = await frappe.db.get_doc('Purchase Order', poName);
  const firstItem = (po.items && po.items[0]) ? po.items[0] : {};
  let subTasks = [];
  if (po.custom_sub_gantt_json) { try { subTasks = JSON.parse(po.custom_sub_gantt_json); } catch(e) {} }
  if (!subTasks || !subTasks.length) subTasks = buildDefaultSubTasks(po.transaction_date, po.schedule_date);

  const d = new frappe.ui.Dialog({
    title: `🏢 [${po.supplier_name}] 발주 상세 및 일자별 세부 공정 간트차트 (${po.name})`,
    size: 'extra-large',
    fields: [{ fieldname: 'detail_html', fieldtype: 'HTML' }],
    primary_action_label: '💾 세부 일정 저장',
    primary_action: async () => { await saveDetailChanges(true); }
  });
  setTimeout(() => {
    const md = d.$wrapper.find('.modal-dialog')[0];
    if (md) { md.style.maxWidth = '92vw'; md.style.width = '92vw'; }
  }, 50);

  async function saveDetailChanges(closeAfter = false) {
    const wrap = d.fields_dict.detail_html.$wrapper[0];
    const updatedTasks = [];
    wrap.querySelectorAll('.subtask-row').forEach(tr => {
      updatedTasks.push({
        step: tr.querySelector('.st-name').value,
        start: tr.querySelector('.st-start').value,
        end: tr.querySelector('.st-end').value,
        status: tr.querySelector('.st-status').value,
        note: tr.querySelector('.st-note').value
      });
    });
    subTasks = updatedTasks;
    await frappe.db.set_value('Purchase Order', poName, {
      supplier_name: wrap.querySelector('#dtl-supplier').value,
      custom_target_line: wrap.querySelector('#dtl-line').value,
      custom_target_machine: wrap.querySelector('#dtl-machine').value,
      transaction_date: wrap.querySelector('#dtl-tx-date').value,
      schedule_date: wrap.querySelector('#dtl-sch-date').value,
      custom_delivery_stage: wrap.querySelector('#dtl-stage').value,
      custom_payment_milestone: wrap.querySelector('#dtl-milestone').value,
      custom_sub_gantt_json: JSON.stringify(subTasks)
    });
    frappe.show_alert({ message: '세부 간트차트가 저장되었습니다!', indicator: 'green' });
    loadAllBoardData();
    if (closeAfter) d.hide(); else renderDetailModalContent();
  }

  function renderDetailModalContent() {
    const wrap = d.fields_dict.detail_html.$wrapper[0];
    let minD = po.transaction_date || frappe.datetime.get_today();
    let maxD = po.schedule_date || frappe.datetime.add_days(minD, 20);
    subTasks.forEach(t => { if (t.start && t.start < minD) minD = t.start; if (t.end && t.end > maxD) maxD = t.end; });
    const totalDays = Math.max(5, frappe.datetime.get_diff(maxD, minD) + 1);
    const tickStep = totalDays <= 20 ? 1 : (totalDays <= 45 ? 2 : 5);
    let ticksHtml = '';
    for (let i = 0; i <= totalDays; i += tickStep) {
      const curD = frappe.datetime.add_days(minD, i);
      ticksHtml += `<span style="position:absolute; left:${Math.min(98, Math.round((i / totalDays) * 100))}%; transform:translateX(-50%); font-size:10px; font-weight:700;">${curD.substring(5)}</span>`;
    }
    const toPct = (dStr) => dStr ? Math.max(0, Math.min(96, Math.round((frappe.datetime.get_diff(dStr, minD) / totalDays) * 100))) : 0;
    const todayPct = toPct(frappe.datetime.get_today());

    const ganttBarsHtml = subTasks.map(t => {
      const sP = toPct(t.start), eP = Math.max(sP + 5, toPct(t.end)), wP = Math.min(100 - sP, eP - sP);
      const barClr = t.status === '완료' ? '#10b981' : (t.status === '진행중' ? '#2563eb' : '#f59e0b');
      return `
        <tr>
          <td style="padding:7px 10px; font-weight:800; border:1px solid #cbd5e1; background:#f8fafc;">${t.step}</td>
          <td style="padding:7px 10px; text-align:center; border:1px solid #cbd5e1;">${t.start} ~ <b>${t.end}</b></td>
          <td style="padding:7px 10px; text-align:center; border:1px solid #cbd5e1;"><span style="padding:2px 7px; border-radius:4px; font-size:11px; font-weight:700; color:#fff; background:${barClr};">${t.status}</span></td>
          <td style="position:relative; width:55%; border:1px solid #cbd5e1; background:repeating-linear-gradient(to right, #fff 0%, #fff 4.8%, #f1f5f9 5%); height:36px; padding:0;">
            <div style="position:absolute; top:0; bottom:0; left:${todayPct}%; width:2px; background:#dc2626; z-index:3;"></div>
            <div style="position:absolute; top:6px; left:${sP}%; width:${wP}%; height:24px; background:${barClr}; color:#fff; border-radius:5px; font-size:11px; font-weight:700; line-height:24px; padding:0 8px; overflow:hidden; white-space:nowrap;">${t.step} (${t.start.substring(5)}~${t.end.substring(5)})</div>
