          <div style="display:flex; gap:8px;">
            <button class="btn btn-sm btn-success" id="btn-dtl-complete">✔ 완료 처리</button>
            <button class="btn btn-sm btn-default" id="btn-dtl-print">🖨️ 인쇄</button>
            <button class="btn btn-sm btn-danger" id="btn-dtl-delete">🗑️ 삭제</button>
