            <label style="font-size:11.5px; font-weight:700;">현재 진행단계</label>
            <select id="dtl-stage" class="form-control input-sm">
              <option value="1. 발주확정·선급금지급 (Order Confirmed)" ${(po.custom_delivery_stage||'').includes('1.')?'selected':''}>1. 발주확정·선급금지급</option>
              <option value="2. 메이커 제작중 (In Production)" ${(po.custom_delivery_stage||'').includes('2.')?'selected':''}>2. 메이커 제작중</option>
              <option value="3. 출하전 검사완료 (FAT Passed)" ${(po.custom_delivery_stage||'').includes('3.')?'selected':''}>3. 출하전 검사완료 (FAT)</option>
              <option value="4. 공장 입고·설치중 (Delivered & Installing)" ${(po.custom_delivery_stage||'').includes('4.')?'selected':''}>4. 공장 입고·설치중</option>
              <option value="5. 시운전(SAT)·검수완료 (SAT Completed)" ${(po.custom_delivery_stage||'').includes('5.')?'selected':''}>5. 시운전(SAT)·검수완료</option>
            </select>
          </div>
          <div><label style="font-size:11.5px; font-weight:700;">발주 시작일</label><input type="date" id="dtl-tx-date" class="form-control input-sm" value="${po.transaction_date || ''}"></div>
