          <div style="grid-column:span 2;"><label style="font-size:11.5px; font-weight:700;">대금 결제조건</label><input type="text" id="dtl-milestone" class="form-control input-sm" value="${po.custom_payment_milestone || ''}"></div>
        </div>
        <table style="width:100%; border-collapse:collapse; font-size:12px; margin-bottom:14px;">
          <thead>
            <tr style="background:#e2e8f0;">
              <th style="padding:8px; border:1px solid #cbd5e1; width:23%;">세부 진행 단계</th>
              <th style="padding:8px; border:1px solid #cbd5e1; width:15%; text-align:center;">시작일 ~ 종료일</th>
              <th style="padding:8px; border:1px solid #cbd5e1; width:7%; text-align:center;">상태</th>
              <th style="padding:14px 8px 6px 8px; border:1px solid #cbd5e1; width:55%; position:relative;"><div style="position:relative; height:14px; width:100%;">${ticksHtml}</div></th>
            </tr>
          </thead>
          <tbody>${ganttBarsHtml}</tbody>
        </table>
        <div style="background:#f8fafc; padding:12px; border:1px solid #cbd5e1; border-radius:8px;">
