    wrap.querySelector('#btn-add-subtask').onclick = () => {
      const lastEnd = subTasks.length ? subTasks[subTasks.length - 1].end : frappe.datetime.get_today();
      subTasks.push({ step: `${subTasks.length + 1}. 추가 세부 일정`, start: lastEnd, end: frappe.datetime.add_days(lastEnd, 5), status: '대기', note: '' });
      renderDetailModalContent();
    };
    wrap.querySelector('#btn-refresh-subgantt').onclick = () => saveDetailChanges(false);
    wrap.querySelectorAll('.btn-del-subtask').forEach(btn => {
      btn.onclick = () => { subTasks.splice(Number(btn.getAttribute('data-idx')), 1); renderDetailModalContent(); };
    });
    wrap.querySelector('#btn-dtl-complete').onclick = async () => {
      subTasks.forEach(t => t.status = '완료');
      await frappe.db.set_value('Purchase Order', poName, { custom_delivery_stage: '5. 시운전(SAT)·검수완료 (SAT Completed)', per_received: 100, status: 'Completed', custom_sub_gantt_json: JSON.stringify(subTasks) });
      d.hide(); loadAllBoardData();
    };
    wrap.querySelector('#btn-dtl-print').onclick = () => { d.hide(); frappe.set_route('print', 'Purchase Order', poName); };
    wrap.querySelector('#btn-dtl-delete').onclick = () => { d.hide(); window.deleteRecord('Purchase Order', poName, po.supplier_name); };
  }
  d.show();
  renderDetailModalContent();
};

