window.openQuickSpareModal = async function(assetName = null, rowIdx = null) {
  const assetOptions = cachedData.assets.map(a => ({ label: `${a.custom_machine_no || a.name} - ${a.asset_name}`, value: a.name }));
  let existingRow = null;
  if (assetName && rowIdx !== null) {
    const doc = await frappe.db.get_doc('Asset', assetName);
    if (doc.custom_spare_parts) existingRow = doc.custom_spare_parts[rowIdx];
  }
  const overrides = { asset_id: assetName || appState.selectedAssetId || (assetOptions[0] && assetOptions[0].value) };
  if (existingRow) overrides.supplier_text = existingRow.supplier;

  const d = new frappe.ui.Dialog({
    title: existingRow ? `✏️ 부품·단가 수정 (${existingRow.part_name})` : '➕ 장비별 부품 및 단가 추가',
    size: 'large',
    fields: buildDialogFieldsFromSchema('sp', existingRow, assetOptions, overrides),
    primary_action_label: '✔ 부품·단가 저장',
    primary_action: async () => {
      const vals = d.get_values() || {};
      const targetId = vals.asset_id || assetName || appState.selectedAssetId;
      const supName = await ensureSupplier(vals.supplier_text);
      const itemCode = existingRow ? existingRow.part_item : await ensureItem(vals.part_name, false);
      const doc = await frappe.db.get_doc('Asset', targetId);
      if (!doc.custom_spare_parts) doc.custom_spare_parts = [];
      const rowData = {
        part_item: itemCode, part_name: vals.part_name || '예비부품', part_spec: vals.part_spec || '-',
        unit_price: Number(vals.unit_price || 0), qty_per_machine: Number(vals.qty_per_machine || 1),
        pm_cycle: vals.pm_cycle || '분기 (3개월)', supplier: supName, lead_time_days: Number(vals.lead_time_days || 5), remarks: vals.remarks || ''
      };
      if (existingRow && rowIdx !== null) Object.assign(doc.custom_spare_parts[rowIdx], rowData);
      else doc.custom_spare_parts.push(rowData);
      await frappe.call({ method: 'frappe.client.save', args: { doc: doc } });
      frappe.show_alert({ message: '부품 및 단가가 저장되었습니다!', indicator: 'green' });
      d.hide(); loadAllBoardData();
    }
  });
  d.show();
};

window.deleteSpareRow = function(assetName, rowIdx, partName) {
  frappe.confirm(`<b>[${partName}]</b> 항목을 삭제하시겠습니까?`, async () => {
    const doc = await frappe.db.get_doc('Asset', assetName);
    if (doc.custom_spare_parts && doc.custom_spare_parts.length > rowIdx) {
      doc.custom_spare_parts.splice(rowIdx, 1);
      await frappe.call({ method: 'frappe.client.save', args: { doc: doc } });
      loadAllBoardData();
    }
  });
};

