          <button class="btn btn-xs btn-danger btn-del-snap" data-snap="${s.name}">🗑️ 삭제</button>
        </td>
      </tr>
    `).join('');
    wrap.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
        <b>실수로 삭제·수정했을 때 원하는 시점의 [⏪ 이 시점으로 복원]을 누르세요.</b>
        <div style="display:flex; gap:6px;">
          <input type="text" id="inp-new-bkp-title" class="form-control input-sm" value="수동 백업 (${frappe.datetime.now_datetime().substring(0, 16)})" style="width:200px;">
          <button class="btn btn-sm btn-primary" id="btn-modal-create-bkp">💾 새 백업 저장</button>
          <label class="btn btn-sm btn-default" style="margin:0; cursor:pointer;">📂 백업파일(.json) 불러오기 <input type="file" id="inp-upload-bkp-file" accept=".json" style="display:none;"></label>
        </div>
      </div>
      <table class="hvs-table">
        <thead><tr><th>번호</th><th>백업 메모</th><th class="center">일시</th><th>요약</th><th class="center">복원 / 파일저장 / 삭제</th></tr></thead>
        <tbody>${rowsHtml || '<tr><td colspan="5" class="center">백업이 없습니다.</td></tr>'}</tbody>
      </table>
    `;
    wrap.querySelector('#btn-modal-create-bkp').onclick = async () => {
      await frappe.call({ method: 'hvs_create_snapshot', args: { title: wrap.querySelector('#inp-new-bkp-title').value || '수동 백업' } });
      renderBackupList();
    };
    wrap.querySelector('#inp-upload-bkp-file').onchange = (e) => {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
        frappe.confirm(`[${file.name}] 파일로 복원하시겠습니까?`, async () => {
          await frappe.call({ method: 'hvs_restore_snapshot', args: { raw_json: ev.target.result } });
          d.hide(); loadAllBoardData();
        });
      };
      reader.readAsText(file);
    };
    wrap.querySelectorAll('.btn-restore-snap').forEach(btn => {
      btn.onclick = () => {
        frappe.confirm(`<b>[${btn.getAttribute('data-title')}]</b> 시점으로 복원하시겠습니까?`, async () => {
          await frappe.call({ method: 'hvs_restore_snapshot', args: { snap_name: btn.getAttribute('data-snap') } });
          d.hide(); loadAllBoardData();
        });
      };
    });
    wrap.querySelectorAll('.btn-dl-snap').forEach(btn => {
      btn.onclick = async () => {
        const snapDoc = await frappe.db.get_doc('HVS Backup Snapshot', btn.getAttribute('data-snap'));
        const url = URL.createObjectURL(new Blob([snapDoc.snapshot_json], { type: 'application/json;charset=utf-8' }));
        const a = document.createElement('a'); a.href = url; a.download = `ERP_백업_${snapDoc.name}.json`; a.click();
      };
    });
    wrap.querySelectorAll('.btn-del-snap').forEach(btn => {
      btn.onclick = async () => {
        await frappe.call({ method: 'hvs_delete_doc', args: { dt: 'HVS Backup Snapshot', dn: btn.getAttribute('data-snap') } });
        renderBackupList();
      };
    });
  }
  d.show();
  renderBackupList();
};

