async function loadAllBoardData() {
  await loadState();
  const pos = await frappe.db.get_list('Purchase Order', {
    fields: ['name', 'supplier_name', 'transaction_date', 'schedule_date', 'net_total', 'grand_total', 'status', 'per_received', 'custom_po_category', 'custom_target_line', 'custom_target_machine', 'custom_delivery_stage', 'custom_payment_milestone', 'custom_extra_fields_json'],
    order_by: 'transaction_date desc', limit: 50
  });
  const assets = await frappe.db.get_list('Asset', {
    fields: ['name', 'asset_name', 'custom_machine_no', 'custom_line_name', 'custom_equipment_type', 'custom_maker', 'custom_model_no', 'custom_controller_spec', 'net_purchase_amount', 'custom_arrival_date', 'custom_commissioning_date', 'custom_installation_status', 'custom_chk_utility', 'custom_chk_leveling', 'custom_chk_test_cut', 'custom_chk_training', 'custom_pm_cycle_summary', 'custom_next_pm_date', 'custom_extra_fields_json'],
    order_by: 'creation asc', limit: 50
  });
  const repairs = await frappe.db.get_list('Asset Repair', {
    fields: ['name', 'asset', 'asset_name', 'failure_date', 'repair_status', 'custom_failure_category', 'custom_alarm_code', 'custom_doc_no', 'custom_engineer_name', 'actions_performed', 'custom_root_cause', 'custom_technical_parameters', 'custom_preventive_action', 'total_repair_cost', 'repair_cost', 'custom_extra_fields_json'],
    order_by: 'failure_date desc', limit: 50
  });
  const pmLogs = await frappe.db.get_list('Asset Maintenance Log', {
    fields: ['name', 'asset_name', 'task_name', 'maintenance_type', 'periodicity', 'due_date', 'maintenance_status', 'description', 'actions_performed', 'custom_extra_fields_json'],
    order_by: 'due_date asc', limit: 50
  });
  const spRows = [];
  for (const a of assets) {
    const fullDoc = await frappe.db.get_doc('Asset', a.name);
    if (fullDoc && fullDoc.custom_spare_parts) {
      fullDoc.custom_spare_parts.forEach((sp, idx) => {
        spRows.push({ asset_id: a.name, row_idx: idx, machine_no: a.custom_machine_no || a.asset_name, asset_name: a.asset_name, ...sp });
      });
    }
  }
  cachedData = { pos, assets, spRows, repairs, pmLogs };
  renderSidebar();
  renderSingleStage();
}

loadAllBoardData();

