Server Script.script:
dt = frappe.form_dict.get("dt")
dn = frappe.form_dict.get("dn")
if dt and dn and frappe.db.exists(dt, dn):
    if dt == "Asset":
        for am in frappe.get_all("Asset Maintenance", filters={"asset_name": dn}, pluck="name"):
            for aml in frappe.get_all("Asset Maintenance Log", filters={"asset_maintenance": am}, pluck="name"):
                frappe.db.set_value("Asset Maintenance Log", aml, "docstatus", 2)
                frappe.delete_doc("Asset Maintenance Log", aml, force=1, ignore_permissions=True)
            frappe.delete_doc("Asset Maintenance", am, force=1, ignore_permissions=True)
        for ar in frappe.get_all("Asset Repair", filters={"asset": dn}, pluck="name"):
            frappe.db.set_value("Asset Repair", ar, "docstatus", 2)
            frappe.delete_doc("Asset Repair", ar, force=1, ignore_permissions=True)
        for mov_item in frappe.get_all("Asset Movement Item", filters={"asset": dn}, fields=["parent"]):
            if frappe.db.exists("Asset Movement", mov_item.parent):
                frappe.db.set_value("Asset Movement", mov_item.parent, "docstatus", 2)
                frappe.delete_doc("Asset Movement", mov_item.parent, force=1, ignore_permissions=True)
    if dt == "Purchase Order":
        for pi_item in frappe.get_all("Purchase Invoice Item", filters={"purchase_order": dn}, pluck="name"):
            frappe.db.set_value("Purchase Invoice Item", pi_item, "purchase_order", None)
        for pr_item in frappe.get_all("Purchase Receipt Item", filters={"purchase_order": dn}, pluck="name"):
            frappe.db.set_value("Purchase Receipt Item", pr_item, "purchase_order", None)
    if dt == "Asset Maintenance Log":
        task_id = frappe.db.get_value("Asset Maintenance Log", dn, "task")
        frappe.db.set_value("Asset Maintenance Log", dn, "docstatus", 2)
        frappe.delete_doc("Asset Maintenance Log", dn, force=1, ignore_permissions=True)
        if task_id and frappe.db.exists("Asset Maintenance Task", task_id):
            frappe.delete_doc("Asset Maintenance Task", task_id, force=1, ignore_permissions=True)
        frappe.response["message"] = "deleted"
    else:
        if dt in ["Purchase Order", "Asset", "Asset Repair", "Purchase Invoice", "Purchase Receipt"]:
            frappe.db.set_value(dt, dn, "docstatus", 2)
        frappe.delete_doc(dt, dn, force=1, ignore_permissions=True)
        frappe.response["message"] = "deleted"
else:
    frappe.response["message"] = "not_found"
